ng Gaussian elimination\n# Augment matrix\nM = [[A11, A12, A13, B1],\n     [A21, A22, A23, B2],\n     [A31, A32, A33, B3]]\n\n# Print matrix\nfor row in M:\n    print(row)\n\nprint(\"\\nSolving...\")\n\n# Forward elimination\n# Divide first row by A11\nfactor = M[0][0]\nfor i in range(4):\n    M[0][i] /= factor\n    \n# Eliminate first variable from row 2\nfactor = M[1][0]\nfor i in range(4):\n    M[1][i] -= factor * M[0][i]\n\n# Eliminate first variable from row 3  \nfactor = M[2][0]\nfor i in range(4):\n    M[2][i] -= factor * M[0][i]\n\n# Now eliminate second variable from row 3\nfactor = M[2][1]\nfor i in range(4):\n    M[2][i] -= factor * M[1][i]\n\n# Back substitution\n# Solve for a, b, c\nc = M[2][3] / M[2][2]\nb = (M[1][3] - M[1][2]*c) / M[1][1]\na = (M[0][3] - M[0][1]*b - M[0][2]*c) / M[0][0]\n\nprint(f\"\\na = {a}\")\nprint(f\"b = {b}\")\nprint(f\"c = {c}\")\n\n# Verify by computing original values\nprint(\"\\nVerification of fit:\")\nfor xi, yi in zip(x, y):\n    y_fit = a*xi**2 + b*xi + c\n    print(f\"x={xi}, actual={yi}, fitted={y_fit:.2f}\")\n\n# Predict for x = 7 (April 1970)\nx_pred = 7\ny_pred = a*x_pred**2 + b*x_pred + c\n\nprint(f\"\\nProjected total assets for April 1970 (x={x_pred}): {y_pred}\")\nprint(f\"Rounded to nearest integer: {round(y_pred)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
